-- ----------------------------------------------------------------------------
-- TransactionTypes: Table: TransactionTypes
-- ----------------------------------------------------------------------------
CREATE TABLE transaction_types (
  transaction_type_id                 TEXT                 PRIMARY KEY,         -- Type identifier (Purchase, Sale, Adjustment).
  description                         TEXT                                      -- What this transaction type represents.
);
COMMENT ON TABLE transaction_types IS 'Table: TransactionTypes';
COMMENT ON COLUMN transaction_types.transaction_type_id IS 'Type identifier (Purchase, Sale, Adjustment).';
COMMENT ON COLUMN transaction_types.description IS 'What this transaction type represents.';

-- ----------------------------------------------------------------------------
-- Products: Table: Products
-- ----------------------------------------------------------------------------
CREATE TABLE products (
  product_id                          TEXT                 PRIMARY KEY,         -- Product identifier (SKU or natural key).
  unit_price                          NUMERIC             ,                     -- Price per unit in dollars.
  reorder_level                       INTEGER                                   -- Minimum quantity before reorder is recommended.
);
COMMENT ON TABLE products IS 'Table: Products';
COMMENT ON COLUMN products.product_id IS 'Product identifier (SKU or natural key).';
COMMENT ON COLUMN products.unit_price IS 'Price per unit in dollars.';
COMMENT ON COLUMN products.reorder_level IS 'Minimum quantity before reorder is recommended.';

-- ----------------------------------------------------------------------------
-- Transactions: Table: Transactions
-- ----------------------------------------------------------------------------
CREATE TABLE transactions (
  transaction_id                      TEXT                 PRIMARY KEY,         -- Unique transaction identifier.
  product                             TEXT                ,                     -- Reference to the product being adjusted.
  transaction_type                    TEXT                ,                     -- Type of transaction (Purchase, Sale, Adjustment).
  quantity                            INTEGER             ,                     -- Quantity adjustment (positive for purchases/returns, negative for sales).
  transaction_date                    TIMESTAMPTZ         ,                     -- When the transaction occurred.
  notes                               TEXT                                      -- Optional notes about this transaction.
);
COMMENT ON TABLE transactions IS 'Table: Transactions';
COMMENT ON COLUMN transactions.transaction_id IS 'Unique transaction identifier.';
COMMENT ON COLUMN transactions.product IS 'Reference to the product being adjusted.';
COMMENT ON COLUMN transactions.transaction_type IS 'Type of transaction (Purchase, Sale, Adjustment).';
COMMENT ON COLUMN transactions.quantity IS 'Quantity adjustment (positive for purchases/returns, negative for sales).';
COMMENT ON COLUMN transactions.transaction_date IS 'When the transaction occurred.';
COMMENT ON COLUMN transactions.notes IS 'Optional notes about this transaction.';

